typedef struct {
  int *in;
  int inSize;
  int *out;
  int outSize;
} MyQueue;

MyQueue *myQueueCreate(void) {
  MyQueue *obj = (MyQueue *)malloc(sizeof(MyQueue));
  obj->in = (int *)malloc(sizeof(int) * 100000);
  obj->out = (int *)malloc(sizeof(int) * 100000);
  obj->inSize = obj->outSize = 0;
  return obj;
}

void myQueuePush(MyQueue *obj, int x) {
  obj->in[obj->inSize++] = x;
}

static void transfer(MyQueue *obj) {
  if (obj->outSize == 0) {
    while (obj->inSize > 0) {
      obj->out[obj->outSize++] = obj->in[--obj->inSize];
    }
  }
}

int myQueuePop(MyQueue *obj) {
  transfer(obj);
  return obj->out[--obj->outSize];
}

int myQueuePeek(MyQueue *obj) {
  transfer(obj);
  return obj->out[obj->outSize - 1];
}

bool myQueueEmpty(MyQueue *obj) {
  return obj->inSize == 0 && obj->outSize == 0;
}

void myQueueFree(MyQueue *obj) {
  free(obj->in);
  free(obj->out);
  free(obj);
}

class MyQueue {
  stack<int> in;
  stack<int> out;

  void transfer() {
    if (out.empty()) {
      while (!in.empty()) {
        out.push(in.top());
        in.pop();
      }
    }
  }

public:
  MyQueue() {}
  void push(int x) { in.push(x); }
  int pop() {
    transfer();
    int v = out.top();
    out.pop();
    return v;
  }
  int peek() {
    transfer();
    return out.top();
  }
  bool empty() { return in.empty() && out.empty(); }
};

type MyQueue struct {
	in  []int
	out []int
}

func Constructor() MyQueue {
	return MyQueue{}
}

func (q *MyQueue) Push(x int) {
	q.in = append(q.in, x)
}

func (q *MyQueue) transfer() {
	if len(q.out) == 0 {
		for len(q.in) > 0 {
			q.out = append(q.out, q.in[len(q.in)-1])
			q.in = q.in[:len(q.in)-1]
		}
	}
}

func (q *MyQueue) Pop() int {
	q.transfer()
	v := q.out[len(q.out)-1]
	q.out = q.out[:len(q.out)-1]
	return v
}

func (q *MyQueue) Peek() int {
	q.transfer()
	return q.out[len(q.out)-1]
}

func (q *MyQueue) Empty() bool {
	return len(q.in) == 0 && len(q.out) == 0
}

class MyQueue {
  private Deque<Integer> in = new ArrayDeque<>();
  private Deque<Integer> out = new ArrayDeque<>();

  public MyQueue() {}

  public void push(int x) {
    in.push(x);
  }

  private void transfer() {
    if (out.isEmpty()) {
      while (!in.isEmpty()) out.push(in.pop());
    }
  }

  public int pop() {
    transfer();
    return out.pop();
  }

  public int peek() {
    transfer();
    return out.peek();
  }

  public boolean empty() {
    return in.isEmpty() && out.isEmpty();
  }
}

class MyQueue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def push(self, x: int) -> None:
        self.in_stack.append(x)

    def _transfer(self):
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def pop(self) -> int:
        self._transfer()
        return self.out_stack.pop()

    def peek(self) -> int:
        self._transfer()
        return self.out_stack[-1]

    def empty(self) -> bool:
        return not self.in_stack and not self.out_stack

impl MyQueue {
  pub fn new() -> Self {
    MyQueue {
      in_stack: vec![],
      out_stack: vec![],
    }
  }

  pub fn push(&mut self, x: i32) {
    self.in_stack.push(x);
  }

  fn transfer(&mut self) {
    if self.out_stack.is_empty() {
      while let Some(v) = self.in_stack.pop() {
        self.out_stack.push(v);
      }
    }
  }

  pub fn pop(&mut self) -> i32 {
    self.transfer();
    self.out_stack.pop().unwrap()
  }

  pub fn peek(&mut self) -> i32 {
    self.transfer();
    *self.out_stack.last().unwrap()
  }

  pub fn empty(&self) -> bool {
    self.in_stack.is_empty() && self.out_stack.is_empty()
  }
}

class MyQueue {
  private inStack: number[] = [];
  private outStack: number[] = [];

  push(x: number): void {
    this.inStack.push(x);
  }

  private transfer(): void {
    if (this.outStack.length === 0) {
      while (this.inStack.length > 0) this.outStack.push(this.inStack.pop()!);
    }
  }

  pop(): number {
    this.transfer();
    return this.outStack.pop()!;
  }

  peek(): number {
    this.transfer();
    return this.outStack[this.outStack.length - 1];
  }

  empty(): boolean {
    return this.inStack.length === 0 && this.outStack.length === 0;
  }
}
